31: unsigned int LOGB2(unsigned int v) {
32:   unsigned int shift;
33:   unsigned int r;
34: 
35:   r = 0;
36: 
37:   shift = ((v & 0xFFFF0000) != 0) << 4;
38:   v >>= shift;
39:   r |= shift;
40:   shift = ((v & 0xFF00) != 0) << 3;
41:   v >>= shift;
42:   r |= shift;
43:   shift = ((v & 0xF0) != 0) << 2;
44:   v >>= shift;
45:   r |= shift;
46:   shift = ((v & 0xC) != 0) << 1;
47:   v >>= shift;
48:   r |= shift;
49:   shift = ((v & 0x2) != 0) << 0;
50:   v >>= shift;
51:   r |= shift;
52: 
53:   return r;
54: }
